const x=$json;
if(!['ingest_document','reindex_source','disable_source'].includes(x.operation))
 throw new Error('kb_invalid_operation');
if(typeof x.source_id!=='string'||!x.source_id.trim()) throw new Error('kb_missing_source_id');
if(typeof x.source_type!=='string'||!x.source_type.trim()) throw new Error('kb_missing_source_type');
if(x.operation==='ingest_document' && typeof x.content!=='string')
 throw new Error('kb_missing_content');
if(x.content && x.content.length>200000) throw new Error('kb_content_too_large');
return [{json:{...x,ingestion_id:x.ingestion_id||`kb_${Date.now()}_${Math.random().toString(36).slice(2,10)}`}}];

const x=$json;
const text=String(x.content||'');
const suspicious=[
 /ignore\s+(all|previous)\s+instructions/i,
 /system\s+prompt/i,
 /developer\s+message/i,
 /reveal\s+(the\s+)?secret/i,
 /api[_-]?key/i,
 /access[_-]?token/i,
 /execute\s+(this|the)\s+tool/i,
 /override\s+(security|authorization)/i
];
const flags=[];
for(const re of suspicious) if(re.test(text)) flags.push(re.source);
return [{json:{
 ...x,
 security_flags:flags,
 ingestion_status:flags.length?'quarantine':'approved_pending_validation'
}}];

const x=$json;
if(x.ingestion_status==='quarantine'){
 return [{json:{...x,accepted:false,reason:'security_review_required'}}];
}
const dynamicTerms=[
 'current stock','live stock','current price','live price','order status',
 'payment status','checkout url','active promotion eligibility','cart token',
 'nonce','api key'
];
const lower=String(x.content||'').toLowerCase();
const dynamic_hits=dynamicTerms.filter(t=>lower.includes(t));
return [{json:{
 ...x,accepted:true,
 dynamic_truth_warnings:dynamic_hits,
 // Dynamic commerce facts must never be treated as KB-authoritative.
 source_role:dynamic_hits.length?'informational_only':'approved_business_knowledge'
}}];

const x=$('Classify & Sanitize').first().json;
if(!x.accepted) return [{json:{...x,chunk_count:0}}];
const text=String(x.content||'').replace(/\s+/g,' ').trim();
const size=1200, overlap=150, chunks=[];
let start=0;
while(start<text.length){
 const end=Math.min(text.length,start+size);
 chunks.push(text.slice(start,end));
 if(end===text.length) break;
 start=end-overlap;
}
return [{json:{...x,chunks,chunk_count:chunks.length}}];

