const db=$('Create KB Document Version').first().json||{};
if(!x.accepted) return [{json:{
 accepted:false,status:'quarantined',source_id:x.source_id,
 ingestion_id:x.ingestion_id,security_flags:x.security_flags||[]
}}];
return [{json:{
 accepted:true,status:'active',source_id:x.source_id,version:String(x.version||''),
 ingestion_id:x.ingestion_id,chunk_count:x.chunk_count||0,
 source_role:x.source_role,
 dynamic_truth_warnings:x.dynamic_truth_warnings||[]
}}];
